class Solution {
public:
    bool isDigitorialPermutation(int n) {
        int fact[10];fact[0]=1;
        for(int i=1;i<10;++i)fact[i]=fact[i-1]*i;
        int sum=0, t=n;
        while(t){sum+=fact[t%10];t/=10;}
        string a=to_string(n),b=to_string(sum);
        sort(a.begin(),a.end());sort(b.begin(),b.end());
        return a==b;
    }
};
